from gtlib import *
OV=L('/ganesha/temples/ashtavinayaka/','the Aṣṭavināyaka overview')
GP=L('/ganesha/foundations/ganapatya/','the Gāṇapatya tradition')
SRC=lambda t:[('Temple facts:',f'Wikipedia, “{t}” and “Ashtavinayaka”, as summarised in our earlier guide; temple trust information.')]
W=[('🛕','Svayambhū','Self-manifested: an image held to have appeared by itself.'),('🟠','Sindūr','The orange-red paste that coats many Gaṇeśa images.'),('🪔','Dīpamāḷā','A lamp tower of stone, lit with many lamps at festivals.'),('🌿','Dūrvā','The three-bladed grass dear to Gaṇeśa.'),('🙏','Āratī','Waving of lamps, with the song “Sukhakartā Duḥkhahartā”.'),('🌗','Caturthī · Saṅkaṣṭī','The bright and dark fourth days, sacred to Gaṇeśa.')]
# ---------- THEŪR ----------
temple(5,dict(kicker='AṢṬAVINĀYAKA 5 OF 8 · THE WISH-JEWEL · THE PESHWA’S GAṆEŚA',
cov=covart('A temple by a lake, a glowing jewel above it, and a king at prayer',g(220,170,1.2,palace())+'<ellipse cx="380" cy="190" rx="60" ry="12" fill="#8fb8de"/>'+'<circle cx="220" cy="60" r="16" fill="#e74c3c" stroke="#ffd60a" stroke-width="4"/>'+g(90,190,1,person('#8e1f17'))),
cap='The wish-jewel',how='The <b>wish-jewel</b> Cintāmaṇi, the prince who stole it, the image, the young <b>Peshwa</b> who died here, and Moraya Gosāvī’s road.',
desc='Theūr’s Cintāmaṇi explained: the legend of the wish-jewel and the sage Kapila, the east-facing image, Peshwa Mādhavrāo I who died here in 1772, Moraya Gosāvī, and visiting the Aṣṭavināyaka closest to Pune.',
fw=['Only about 22 km from Pune, near where the Mula–Mutha meets the Bhīmā, stands <b>Cintāmaṇi</b>, the Gaṇeśa named after the wish-granting jewel. He was the family deity of the Peshwas; one of them, still young, came here to die.','This guide covers the legend of the jewel, the image, the temple, the Peshwa Mādhavrāo, and Moraya Gosāvī, who rested here on his walks to Morgaon. See '+OV+'.'],fwtk=[('z','A jewel that grants wishes?'),('b','And a lesson about wanting, Zappy. Wait for the story.')],
glance=[('Where','Theūr, Haveli taluka, Pune district'),('Distance','About 22 km from Pune: the nearest'),('Rivers','Near the meeting of the Mula–Mutha and Bhīmā'),('Form','Cintāmaṇi, facing east, trunk to the left'),('Legend','The wish-jewel recovered from Guṇa for the sage Kapila'),('Peshwa','Mādhavrāo I’s family deity; he died here in 1772'),('Lake','Kadamba-tīrtha behind the temple'),('Saint','Moraya Gosāvī’s halt on the road to Morgaon')],
where=['<b>Closest.</b> Theūr is the nearest of the eight to Pune, an easy half-day trip from the city.','<b>Rivers.</b> It lies near the meeting of the Mula–Mutha and the Bhīmā.','<b>Old name.</b> The place was once called Kadambanagar; the lake behind the temple is Kadamba-tīrtha.'],wtk=[('z','So I can start here from Pune?'),('b','Many do, Zappy, though the circuit proper starts at Morgaon.')],wk='Nearest <b>to Pune</b>.',
lt='THE WISH-JEWEL',ls='Kapila, Guṇa and Cintāmaṇi',strip=strip('Three panels: a sage feeding an army from a glowing jewel; a prince seizing the jewel; Gaṇeśa returning it to the sage',[panel([(sage(),.8),(coins(),.6)],'#fff3cf',150),panel([(person('#8e1f17'),.9),(coins(),.5)],'#fde4e4',150),panel([(ganesha(),.6),(sage(),.7)],'#e3f5e9',150)],['the sage’s feast','the greedy prince','the jewel returned']),lsrc='Gaṇeśa Purāṇa and temple tradition; tellings differ.',
lsteps=['The sage <b>Kapila</b> owned the <b>Cintāmaṇi</b>, a jewel that granted whatever its owner wished.','Prince <b>Guṇa</b> visited with his army; Kapila used the jewel to feast them all.','Guṇa wanted the jewel and took it by force.','Kapila prayed to Gaṇeśa, who fought Guṇa and won the jewel back.','Kapila no longer wanted it. He placed it round Gaṇeśa’s neck, and Gaṇeśa here is <b>Cintāmaṇi</b>.'],ltk=[('z','Kapila gave the jewel away?'),('b','After all that, Zappy. The real treasure was Gaṇeśa.')],lk='The jewel <b>given away</b>.',
more=[('image','THE IMAGE','Cintāmaṇi',gimg('A seated Gaṇeśa with a red jewel in its eyes','facing east'),['<b>Form.</b> Facing east, trunk to the left; the eyes are set with a carbuncle and diamonds.','<b>Svayambhū.</b> Held to be self-manifested.','<b>The door.</b> The temple entrance faces north.'],[('z','Red jewels for a jewel-god?'),('b','Fitting, Zappy.')],'Eyes like <b>jewels</b>.'),
('temple','THE TEMPLE','Chinchwad and the Peshwas',tscene('A temple with a wooden hall and a lake behind',extra='<ellipse cx="460" cy="155" rx="70" ry="12" fill="#8fb8de"/>'),['<b>Builder.</b> The main temple is attributed to Dharaṇīdhar Mahārāj Dev of Chinchwad, of Moraya Gosāvī’s line.','<b>Wooden hall.</b> The Peshwas added a carved wooden outer hall.','<b>Lake.</b> Kadamba-tīrtha lies behind the temple.'],[('z','Wood and stone together?'),('b','Stone for the god, wood for the people, Zappy.')],'Stone and <b>Peshwa wood</b>.'),
('peshwa','THE YOUNG PESHWA','Mādhavrāo I at Theūr',svg(560,160,'A young king lying ill before the temple, attendants at his side',f'<rect width="560" height="160" fill="#2a1f2e"/>'+g(280,130,.9,palace())+g(160,150,1,person('#8e1f17',seat=True))+g(420,150,1,lamp())),['<b>Mādhavrāo I</b> (1745–1772) became Peshwa young and restored Maratha power after Pānipat. Cintāmaṇi was his family deity; he renovated the temple.','<b>His end.</b> Gravely ill with tuberculosis, he came to Theūr and died here in 1772, about 27 years old.','<b>Ramābāī.</b> His wife performed satī here. The episode is remembered at the temple; we record it as history, not as a custom to admire.'],[('z','He came here to die?'),('b','Near his Gaṇeśa, Zappy. A king’s last pilgrimage.')],'A king’s <b>last days</b>.'),
('moraya','MORAYA’S ROAD','Between Chinchwad and Morgaon',svg(560,160,'A saint walking a road between two temples, resting at a third',f'<rect width="560" height="160" fill="#fde9c8"/>'+g(80,140,.7,palace())+g(280,140,.7,palace())+g(480,140,.7,palace())+'<path d="M100 150 L460 150" stroke="#b08a5a" stroke-width="5" stroke-dasharray="10 8"/>'+g(200,150,1,sage())),['<b>The walk.</b> Moraya Gosāvī walked regularly from Chinchwad to Morgaon, and by tradition rested at Theūr.','<b>Saṅkaṣṭī.</b> Tradition links his monthly fast with this temple.','<b>Still walked.</b> Devotees still make the Chinchwad–Morgaon walk by way of Theūr. Read '+GP+'.'],[('z','Walking all that way?'),('b','Every month, Zappy. Devotion has strong legs.')],'The saint’s <b>halt</b>.'),
('meaning','THE TRUE WISH-JEWEL','What Theūr teaches',svg(560,150,'A jewel placed on Gaṇeśa’s chest, glowing',f'<rect width="560" height="150" fill="#fff3cf"/>'+g(280,140,1.3,ganesha())+'<circle cx="280" cy="90" r="10" fill="#e74c3c" stroke="#ffd60a" stroke-width="3"/>'),['<b>Cintā-maṇi.</b> “Thought-jewel”: it grants whatever you think of. The story asks what you would wish for.','<b>Guṇa and Kapila.</b> One grabbed; one gave away. Many read the story as about desire and contentment. (Interpretation.)','<b>The heart.</b> Devotees say the real Cintāmaṇi is a mind fixed on Gaṇeśa.'],[('z','What would you wish for?'),('b','To not need the jewel, Zappy. Like Kapila.')],'The jewel <b>is Gaṇeśa</b>.')],
words=W,gtk=[('z','Any new word?'),('b','Cintāmaṇi itself, Zappy: “thought-jewel”.')],
end=['<b>Where.</b> Theūr, 22 km from Pune.','<b>Form.</b> Cintāmaṇi, facing east.','<b>Legend.</b> The wish-jewel won back for Kapila.','<b>History.</b> Mādhavrāo I’s Gaṇeśa; he died here in 1772.','<b>Saint.</b> Moraya Gosāvī’s halt.'],endnext='Next: '+L('/ganesha/temples/lenyadri/','Leṇyādri')+', the cave of Gaṇeśa’s childhood.',
src=SRC('Chintamani Temple, Theur'),unver='the attribution of the main temple; details of the jewel legend (tellings differ); Moraya Gosāvī’s Saṅkaṣṭī link (tradition).',study='Study notes on Theūr’s Cintāmaṇi.'))
# ---------- LEṆYĀDRI ----------
temple(6,dict(kicker='AṢṬAVINĀYAKA 6 OF 8 · THE CAVE · 283 STEPS',
cov=covart('A hillside of rock-cut caves with a long stairway climbing to one cave',g(220,190,2.4,mountain('#9a8a6a',False))+''.join(f'<rect x="{90+k*45}" y="{120-(k%2)*12}" width="26" height="22" fill="#4a3a2a"/>' for k in range(6))+'<path d="M200 210 L250 128" stroke="#e9d6c0" stroke-width="6" stroke-dasharray="4 3"/>'),
cap='Son of the mountain’s daughter',how='About thirty <b>Buddhist caves</b>, Cave 7 where Gaṇeśa sits, <b>Pārvatī’s penance</b>, the image, and the <b>283 steps</b>.',
desc='Leṇyādri’s Girijātmaja explained: the Buddhist caves of the 1st–3rd centuries, Cave 7 and its Gaṇeśa shrine, Pārvatī’s penance and Gaṇeśa’s childhood, the image, and the climb of 283 steps.',
fw=['High on a hill near Junnar, among about thirty caves cut by Buddhist monks nearly two thousand years ago, sits <b>Girijātmaja</b>, “son of Girijā”, the mountain’s daughter Pārvatī. It is the only Aṣṭavināyaka in a cave, and the only one on a mountain.','Tradition says Pārvatī did penance here for a son and that Gaṇeśa spent his childhood here. This guide covers the caves, Cave 7, the legend, the image and the climb. See '+OV+'.'],fwtk=[('z','Gaṇeśa in a Buddhist cave?'),('b','Two traditions in one rock, Zappy.')],
glance=[('Where','Leṇyādri, near Junnar, Pune district'),('Form','Girijātmaja, “son of Girijā (Pārvatī)”'),('Setting','Cave 7 of about 30 Buddhist rock-cut caves'),('Dates','Caves of the 1st–3rd century CE'),('Steps','283, in eight flights'),('Unique','The only Aṣṭavināyaka on a mountain, in a cave'),('Care','Protected by the Archaeological Survey of India'),('Light','Daylight only')],
where=['<b>Junnar.</b> Leṇyādri lies near the old town of Junnar, about 95 km north of Pune, on the Kukaḍī river side of the hills.','<b>The hill.</b> The caves face south across the valley; Shivneri fort, birthplace of Śivājī, stands nearby.','<b>Ojhar next.</b> Ojhar is close by, so many pilgrims visit both on one day.'],wtk=[('z','Śivājī’s fort is nearby?'),('b','Shivneri, Zappy. One valley, many stories.')],wk='Caves above <b>Junnar</b>.',
lt='PĀRVATĪ’S PENANCE',ls='Where Gaṇeśa grew up',strip=strip('Three panels: Pārvatī in penance in a cave; a child Gaṇeśa playing in the cave; the young Gaṇeśa setting out on a peacock',[panel([(mountain('#9a8a6a',False),.7),(devi(sari='#2a9d6f',items=()),.7)],'#fde9c8',150),panel([(ganesha(),.5),(child(),.6)],'#fff3cf',150),panel([(bird('#2a6ab8'),.9),(ganesha(),.4)],'#dfe9f6',150)],['twelve years of tapas','a childhood in the hill','off to fight Sindhu']),lsrc='Gaṇeśa Purāṇa (Tretā age) and temple tradition.',
lsteps=['In the Tretā age, Pārvatī wished for a son and did penance on this hill for twelve years.','Gaṇeśa was born to her here, in the Gaṇeśa Purāṇa’s telling of his Tretā-age form.','He spent his childhood here, about fifteen years, the stories say.','Grown, he rode out on a peacock to destroy the demon Sindhu at '+L('/ganesha/temples/morgaon/','Morgaon')+'.','So Leṇyādri and Morgaon tell two halves of one story: the birth and the victory.'],ltk=[('z','Gaṇeśa grew up in a cave?'),('b','In this telling, Zappy. A mountain childhood for a mountain-mother’s son.')],lk='Two halves of <b>one story</b>.',
more=[('caves','THE BUDDHIST CAVES','Monks before Gaṇeśa',svg(560,160,'A row of cave entrances with a stūpa visible in one',f'<rect width="560" height="160" fill="#d9c9a8"/>'+''.join(f'<rect x="{40+k*85}" y="60" width="60" height="70" rx="8" fill="#4a3a2a"/>' for k in range(6))+'<path d="M300 125 q30 -40 60 0z" fill="#c9a06a"/>'),['<b>About thirty caves.</b> Cut by Buddhist monks between the 1st and 3rd centuries CE, facing south over the valley.','<b>Chapels.</b> Caves 6 and 14 are caityas with stūpas; the rest are vihāras, dwellings for monks, with rock-cut water cisterns.','<b>Inscriptions.</b> Several record gifts by individuals and guilds; Cave 6’s dates to the 2nd century.','<b>Protected.</b> The Archaeological Survey of India looks after the site.'],[('z','Who cut them?'),('b','Buddhist monks, Zappy, nearly two thousand years ago.')],'Monks <b>first</b>.'),
('cave7','CAVE 7','Gaṇeśa’s shrine in a monks’ hall',svg(560,160,'A wide pillared cave hall with a shrine in the back wall',f'<rect width="560" height="160" fill="#4a3a2a"/>'+''.join(f'<rect x="{80+k*80}" y="30" width="16" height="110" fill="#8a7a6a"/>' for k in range(6))+g(280,140,.7,ganesha())),['<b>A vihāra.</b> Cave 7 was a monks’ hall, the largest excavation near Junnar: about 17 by 15 metres with twenty cells.','<b>The shrine.</b> Two central cells were joined to hold Gaṇeśa.','<b>Pillars.</b> The veranda has octagonal pillars topped with animal figures; inside, the hall is open, without pillars.','<b>Daylight.</b> No electric lamps: the cave is lit by the sun.'],[('z','No electric lights?'),('b','Just daylight and oil lamps, Zappy. As the monks had it.')],'A monks’ hall, <b>now Gaṇeśa’s</b>.'),
('image','THE IMAGE AND THE STEPS','Girijātmaja and the climb',svg(560,160,'A long stairway of flights up a hillside to a cave',f'<rect width="560" height="160" fill="#e3f5e9"/>'+''.join(f'<rect x="{60+k*55}" y="{140-k*15}" width="55" height="{20+k*15}" fill="#c9a06a"/>' for k in range(8))+g(500,30,.4,ganesha())),['<b>The image.</b> Facing north, trunk to the left; sources say devotees see it from the rear, and that it is less finely carved than the other seven.','<b>Priests.</b> Worship is by Yajurvedī Brahmins.','<b>283 steps.</b> In eight flights up the hillside. Take water and take your time; arrangements and fees are set by the authorities.'],[('z','283 steps!'),('b','In eight flights, Zappy. Count them as japa.')],'<b>283</b> steps.'),
('meaning','A MOTHER’S PATIENCE','What Leṇyādri teaches',svg(560,150,'A mother and a small child in a cave mouth looking out at the valley',f'<rect width="560" height="150" fill="#fde9c8"/><path d="M180 150 q0 -110 100 -110 q100 0 100 110z" fill="#4a3a2a"/>'+g(260,140,.9,mother())+g(310,140,.6,child())),['<b>Twelve years.</b> Pārvatī waited and worked twelve years for her child. Many read Leṇyādri as about patience in prayer. (Interpretation.)','<b>Shared rock.</b> A Buddhist monastery that became a Hindu shrine: the hill holds both histories.','<b>The climb.</b> The effort of the steps is part of the visit: you come up to Gaṇeśa, he does not come down.'],[('z','Did the monks mind?'),('b','They had left long before, Zappy. The rock remembers them still.')],'<b>Patience</b> in prayer.'),
('junnar','THE JUNNAR VALLEY','Caves, forts and Gaṇeśa',svg(560,160,'A valley with a fort on a hill, cave mouths and a temple',f'<rect width="560" height="160" fill="#e3f5e9"/>'+g(140,150,1.5,mountain('#8a9a6a',False))+g(140,70,.6,flag())+g(330,140,.9,palace())+''.join(f'<rect x="{420+k*30}" y="90" width="18" height="18" fill="#4a3a2a"/>' for k in range(4))),['<b>Shivneri.</b> The hill fort where Śivājī was born stands above Junnar.','<b>More caves.</b> Junnar has several other groups of Buddhist caves, among the largest clusters in India.','<b>Two Gaṇeśas.</b> Leṇyādri and Ojhar are close; most pilgrims visit both in one day.'],[('z','So much in one valley!'),('b','Monks, kings and Gaṇeśa, Zappy. Junnar has them all.')],'A valley <b>of stories</b>.')],
words=W+[('🕳️','Vihāra · Caitya','A monks’ dwelling cave; a prayer hall with a stūpa.')],gtk=[('z','Vihāra and caitya?'),('b','Buddhist words, Zappy. Useful at every cave in Maharashtra.')],
end=['<b>Where.</b> A hill of caves near Junnar.','<b>Form.</b> Girijātmaja, son of Pārvatī.','<b>Legend.</b> Pārvatī’s penance; Gaṇeśa’s childhood.','<b>Setting.</b> Cave 7 of about 30 Buddhist caves.','<b>Climb.</b> 283 steps.'],endnext='Next: '+L('/ganesha/temples/ozar/','Ojhar')+', the golden dome, close by.',
src=SRC('Lenyadri'),unver='the rear-view darśan and the carving quality (sources differ); the length of Gaṇeśa’s childhood (tradition); travel distances (approximate).',study='Study notes on Leṇyādri’s Girijātmaja.'))
# ---------- OJHAR ----------
temple(7,dict(kicker='AṢṬAVINĀYAKA 7 OF 8 · THE LORD OF OBSTACLES · THE GOLDEN DOME',
cov=covart('A temple with a golden dome by a river, a defeated demon bowing',g(220,170,1.3,palace())+'<circle cx="220" cy="95" r="16" fill="#e0a800"/>'+'<path d="M0 195 q220 -14 440 0 v25 h-440z" fill="#8fb8de"/>'+g(360,185,.8,demon())),
cap='Lord of obstacles',how='The demon <b>Vighnāsura</b> who became part of Gaṇeśa’s name, the image, the <b>golden dome</b>, the walls and lamp towers, and the river.',
desc='Ojhar’s Vighneśvara explained: the legend of King Abhinandana and the demon Vighnāsura, the jewelled image, Chimājī Appā’s golden dome, the walled temple on the Kukaḍī, and its festivals.',
fw=['On the Kukaḍī river in Junnar taluka stands <b>Vighneśvara</b>, lord of obstacles, the only Aṣṭavināyaka with a golden dome. His name belongs half to a demon: Vighnāsura, who surrendered and asked to be remembered.','This guide covers the legend, the image, the dome and its war-time donor, the temple, and the festivals. See '+OV+'.'],fwtk=[('z','A demon in Gaṇeśa’s name?'),('b','Gaṇeśa forgave him and kept his name, Zappy.')],
glance=[('Where','Ojhar, Junnar taluka, Pune district'),('River','Kukaḍī, near the Yedgaon dam'),('Distance','About 85 km from Pune, 9 km north of Nārāyaṇgaon'),('Form','Vighneśvara, facing east, trunk to the left'),('Legend','Vighnāsura subdued; his name joined Gaṇeśa’s'),('Dome','Gold-covered, the only one of the eight'),('Patron','Chimājī Appā; renovated 1967'),('Near','Leṇyādri, about 15 km')],
where=['<b>River temple.</b> Ojhar stands on the Kukaḍī river near the Yedgaon dam, about 85 km north of Pune.','<b>Neighbour.</b> Leṇyādri is about 15 km away; pilgrims often pair them.','<b>Walls.</b> A thick stone wall surrounds the temple; visitors can walk along it and look at the river.'],wtk=[('z','Can I walk on the wall?'),('b','You can, Zappy. The river breeze is the reward.')],wk='By the <b>Kukaḍī</b>.',
lt='VIGHNĀSURA',ls='The demon of obstacles',strip=strip('Three panels: a king at a fire sacrifice; a demon wrecking sacrifices; the demon bowing before Gaṇeśa',[panel([(person('#8e1f17',seat=True),.8),(fire(),.7)],'#fde4e4',150),panel([(demon(),1),(fire(),.5)],'#e9e3f5',150),panel([(ganesha(),.6),(demon(),.7)],'#fff3cf',150)],['Abhinandana’s sacrifice','obstacles everywhere','the demon’s plea']),lsrc='Temple tradition, traced by some to the Mudgala Purāṇa.',
lsteps=['King <b>Abhinandana</b> held a great sacrifice but offered no share to Indra.','Indra, furious, sent <b>Kāla</b>, time and death, to destroy it.','Kāla became <b>Vighnāsura</b>, the demon of obstacles, and wrecked sacrifices and good works everywhere.','The sages turned to Gaṇeśa, who fought and subdued the demon.','Vighnāsura begged mercy and asked that his name be joined to Gaṇeśa’s here. So Gaṇeśa is <b>Vighneśvara</b>, and the demon promised to stay away from places where Gaṇeśa is worshipped.'],ltk=[('z','Gaṇeśa kept the demon’s name?'),('b','As a promise, Zappy: where Gaṇeśa is worshipped, obstacles leave.')],lk='Obstacles <b>sent away</b>.',
more=[('image','THE IMAGE','Vighneśvara',gimg('A Gaṇeśa image with gem eyes and a diamond on the forehead, flanked by two brass consorts','facing east'),['<b>Form.</b> Facing east, trunk to the left; eyes set with gems, rubies or emeralds in different accounts, a diamond on the forehead and a jewel in the navel.','<b>Consorts.</b> Brass images of Riddhi and Siddhi on either side.','<b>Pañcāyatana.</b> Sūrya, Śiva, Viṣṇu, Devī and Gaṇeśa stand at the corners of the sanctum.'],[('z','Rubies or emeralds?'),('b','Accounts differ, Zappy. Either way, they shine.')],'Jewelled <b>Vighneśvara</b>.'),
('dome','THE GOLDEN DOME','Chimājī Appā’s gift',svg(560,160,'A temple with a shining golden dome and a commander offering it',f'<rect width="560" height="160" fill="#fde9c8"/>'+g(280,150,1.1,palace())+'<circle cx="280" cy="70" r="20" fill="#e0a800" stroke="#a07800" stroke-width="3"/>'+g(450,150,1.1,person('#1d4f8a'))),['<b>The donor.</b> Chimājī Appā, brother and commander of Peshwa Bājīrāo I.','<b>The victory.</b> After capturing Vasai fort from the Portuguese in 1739, he renovated the temple and covered its dome in gold.','<b>Unique.</b> The only gilded dome among the eight.','<b>Later.</b> Some sources date the temple to 1785; dates vary. It was renovated again in 1967 by the devotee Appā Śāstrī Joshī.'],[('z','Gold for a victory?'),('b','A commander’s thanks, Zappy.')],'A <b>golden</b> thank-you.'),
('temple','THE TEMPLE','Walls, lamps and river',tscene('A walled temple with lamp towers at the gate and a river beside',extra=g(60,150,.8,lamp())+g(500,150,.8,lamp()),river_=True),['<b>Walls.</b> A thick stone wall you can walk along.','<b>Halls.</b> A main hall of about 20 feet and an inner hall of about 10 feet before the sanctum.','<b>Lamp towers.</b> Two dīpamāḷās at the entrance, lit at festivals.','<b>Festivals.</b> Caturthī, Gaṇeśa Jayantī and a Kārtika fair.'],[('z','When are the lamp towers lit?'),('b','At festivals, Zappy. Hundreds of flames.')],'Lamps by <b>the river</b>.'),
('meaning','OBSTACLES','What Ojhar teaches',svg(560,150,'A rock on a path being lifted aside by an elephant trunk',f'<rect width="560" height="150" fill="#e3f5e9"/><path d="M0 120 L560 120" stroke="#b08a5a" stroke-width="10"/><ellipse cx="300" cy="105" rx="40" ry="20" fill="#8a8f9a"/>'+g(220,130,.7,elephant(False))),['<b>Vighna.</b> An obstacle. Gaṇeśa is both Vighneśvara, lord of obstacles, and Vighnahartā, their remover.','<b>Time.</b> The demon was Kāla, time. Many read the story as about delay and bad timing in our work. (Interpretation.)','<b>Forgiveness.</b> Gaṇeśa did not destroy Vighnāsura; he took his surrender and kept his name.'],[('z','So obstacles can be forgiven?'),('b','And put to work, Zappy. That’s Ojhar.')],'Lord <b>of obstacles</b>.'),
('visit','VISITING OJHAR','In the circuit',amap('ozar'),['<b>Seventh.</b> Ojhar comes after Leṇyādri and before Rāñjaṇgāv.','<b>Pairing.</b> With Leṇyādri about 15 km away, the two make a natural day.','<b>Arrangements.</b> Timings and rules are set by the temple trust; check locally.'],[('z','Leṇyādri and Ojhar in one day?'),('b','That’s how most do it, Zappy.')],'Seventh <b>of eight</b>.')],
words=W,gtk=[('z','Vighna, vighneśvara, vighnahartā!'),('b','All one family of words, Zappy.')],
end=['<b>Where.</b> Ojhar on the Kukaḍī, Junnar taluka.','<b>Form.</b> Vighneśvara, jewelled.','<b>Legend.</b> Vighnāsura subdued and named.','<b>Dome.</b> Gilded by Chimājī Appā.','<b>Next.</b> One more, then home to Morgaon.'],endnext='Next: '+L('/ganesha/temples/ranjangaon/','Rāñjaṇgāv')+', Śiva’s Gaṇeśa.',
src=SRC('Vighnahar Ganapati Temple, Ozar'),unver='the gems in the eyes (accounts differ); the temple’s date (1785 or earlier); the Mudgala Purāṇa source of the legend (some sources).',study='Study notes on Ojhar’s Vighneśvara.'))
# ---------- RĀÑJAṆGĀV ----------
temple(8,dict(kicker='AṢṬAVINĀYAKA 8 OF 8 · ŚIVA’S GAṆEŚA · BACK TO MORGAON',
cov=covart('Śiva drawing a bow at three flying cities, a Gaṇeśa temple below',g(120,180,1,shiva())+g(220,170,1.1,palace())+''.join(f'<rect x="{300+k*40}" y="{40+k*10}" width="30" height="18" fill="#e0a800"/>' for k in range(3))),
cap='The great Gaṇapati',how='How <b>Śiva</b> worshipped Gaṇeśa before destroying <b>Tripura</b>, the image and its hidden twin, the temple and the sun, and <b>closing the circle</b>.',
desc='Rāñjaṇgāv’s Mahāgaṇapati explained: Śiva’s worship before destroying Tripurāsura, the seated image and the legend of a hidden ten-trunked form, the east-facing temple, and the return to Morgaon.',
fw=['On the Pune–Ahilyanagar road, about 50 km from Pune, stands <b>Mahāgaṇapati</b>, the great Gaṇapati, the eighth and last of the circuit. Here, the story goes, even Śiva stopped to worship his son before his greatest battle.','This guide covers the legend of Tripura, the image, the temple, its festivals and the return to Morgaon to close the circle. See '+OV+'.'],fwtk=[('z','Śiva worshipped his own son?'),('b','Before fighting Tripura, Zappy. Gaṇeśa first, even for Śiva.')],
glance=[('Where','Rāñjaṇgāv, Shirur taluka, Pune district'),('Distance','About 50 km from Pune'),('Form','Mahāgaṇapati, seated cross-legged, facing east'),('Trunk','To the left; broad forehead'),('Legend','Śiva worships Gaṇeśa before slaying Tripurāsura'),('Patron','Peshwa Mādhavrāo built the stone sanctum'),('Old name','Maṇipur'),('Next','Back to Morgaon to close the circle')],
where=['<b>On the highway.</b> Rāñjaṇgāv lies on the Pune–Ahilyanagar road in Shirur taluka.','<b>Old name.</b> The town was once called Maṇipur.','<b>Last stop.</b> From here pilgrims return to Morgaon to complete the circuit.'],wtk=[('z','Easy to reach?'),('b','Right on the highway, Zappy.')],wk='On the <b>highway</b>.',
lt='ŚIVA AND TRIPURA',ls='Even Śiva begins with Gaṇeśa',strip=strip('Three panels: a demon with three flying cities; Śiva’s chariot with a broken axle; Śiva worshipping Gaṇeśa then loosing one arrow',[panel([(demon(),.8),(palace(),.4)],'#e9e3f5',150),panel([(shiva(),.8),('<path d="M-40 0 h80" stroke="#6a4a2a" stroke-width="6"/>',1)],'#fde4e4',150),panel([(shiva(),.7),(ganesha(),.5),(arrow(),.6)],'#fff3cf',150)],['three flying cities','the broken axle','one arrow']),lsrc='Temple tradition; the Tripura story is told in many Purāṇas.',
lsteps=['The demon <b>Tripurāsura</b> ruled three flying cities of gold, silver and iron; they could be destroyed only by one arrow when they lined up.','Śiva set out to destroy them, but did not first honour Gaṇeśa.','In one telling, the axle of Śiva’s chariot broke. Śiva understood the cause.','He worshipped Gaṇeśa here, at Maṇipur.','Then, with one arrow, he burned the three cities. Read our '+L('/festivals/kartika/kartika-purnima/','Kārtika Pūrṇimā')+' guide for Tripurāri.'],ltk=[('z','The axle broke?'),('b','A reminder, Zappy. Gaṇeśa first, then the arrow.')],lk='<b>Gaṇeśa first</b>, then the arrow.',
more=[('image','THE IMAGE','Mahāgaṇapati',gimg('A broad-foreheaded seated Gaṇeśa flanked by two consorts','facing east · broad forehead'),['<b>Form.</b> Seated cross-legged, facing east, with a broad forehead and the trunk to the left, flanked by Riddhi and Siddhi.','<b>The hidden image.</b> Local belief holds that the true image, with ten trunks and twenty arms, lies in a vault below. This is unproven.','<b>Name.</b> Mahāgaṇapati, the great Gaṇapati: the form Śiva worshipped.'],[('z','Ten trunks?'),('b','A story no one has proved, Zappy. A good one, though.')],'The <b>great</b> Gaṇapati.'),
('temple','THE TEMPLE AND THE SUN','Built for the light',svg(560,160,'A temple facing east with the sun’s rays entering the sanctum',f'<rect width="560" height="160" fill="#fff3cf"/>'+g(300,150,1.1,palace())+g(80,50,1.1,sun())+'<path d="M100 60 L290 120" stroke="#e0a800" stroke-width="3" stroke-dasharray="6 4"/>'),['<b>Facing east.</b> The gate is guarded by Jaya and Vijaya.','<b>The sun.</b> The temple is aligned so that the sun’s rays fall on the image during the sun’s southward course.','<b>Peshwa work.</b> Peshwa Mādhavrāo built the stone sanctum; in 1790 Anyābā Dev was authorised to worship the image.','<b>Age.</b> Some say the architecture recalls the 9th–10th centuries; this is unverified.'],[('z','Sunlight on Gaṇeśa?'),('b','On certain days, Zappy. Planned centuries ago.')],'Built <b>for the sun</b>.'),
('festivals','FESTIVALS','Bhādrapada at Rāñjaṇgāv',svg(560,150,'A festive crowd with lamps and a palanquin',f'<rect width="560" height="150" fill="#fde9c8"/>'+g(280,130,1,palace())+''.join(g(x,140,.5,person('#c0392b')) for x in (100,140,180,380,420,460))),['<b>Gaṇeśa Caturthī</b> in Bhādrapada draws great crowds.','<b>Other days.</b> Saṅkaṣṭī, Aṅgārakī and Gaṇeśa Jayantī.','<b>Arrangements</b> are set by the temple trust; check locally.'],[('z','Busy?'),('b','Very, on Caturthī, Zappy.')],'Caturthī <b>crowds</b>.'),
('circle','CLOSING THE CIRCLE','Back to Morgaon',amap('morgaon'),['<b>Return.</b> After Rāñjaṇgāv, pilgrims go back to '+L('/ganesha/temples/morgaon/','Morgaon')+' to finish where they began.','<b>Why.</b> A circle closed means a vow fulfilled. The journey ends with thanks to Mayūreśvara.','<b>The whole circuit.</b> Eight temples, eight stories, one Gaṇeśa: see '+OV+'.'],[('z','Back to the start?'),('b','That’s what makes it a circle, Zappy.')],'The circle <b>closes</b>.'),
('meaning','GAṆEŚA FIRST','What Rāñjaṇgāv teaches',svg(560,150,'A bow and arrow resting before a small Gaṇeśa',f'<rect width="560" height="150" fill="#fff3cf"/>'+g(200,130,1.3,bow())+g(360,140,1.1,ganesha())),['<b>Even Śiva.</b> The destroyer of Tripura could not begin without honouring Gaṇeśa. Many read this as the humility every great task needs. (Interpretation.)','<b>The broken axle.</b> An obstacle is sometimes a reminder, not an enemy.','<b>The last temple.</b> The circuit ends with the god whom even Śiva worshipped: Gaṇeśa is the first and the greatest.'],[('z','So obstacles can be reminders?'),('b','Sometimes, Zappy. Ask Śiva’s chariot.')],'Humility <b>before the task</b>.')],
words=W+[('🏹','Tripura','The three flying cities Śiva destroyed with one arrow.')],gtk=[('z','Tripura again!'),('b','Śiva’s great victory, Zappy: the Tripurāri story.')],
end=['<b>Where.</b> Rāñjaṇgāv, 50 km from Pune.','<b>Form.</b> Mahāgaṇapati, broad-browed.','<b>Legend.</b> Śiva worships Gaṇeśa before Tripura.','<b>Temple.</b> Aligned to the sun.','<b>Then.</b> Back to Morgaon.'],endnext='Close the circle at '+L('/ganesha/temples/morgaon/','Morgaon')+', or read on: '+L('/ganesha/temples/gokarna/','Gokarṇa')+'.',
src=SRC('Mahaganapati Temple, Ranjangaon'),unver='the hidden ten-trunked image (local belief, unproven); the 9th–10th century architecture claim; the broken-axle variant (tellings differ).',study='Study notes on Rāñjaṇgāv’s Mahāgaṇapati.'))
